import calendar
from datetime import date

def add_month_clamp(d, months=1):
    m = d.month - 1 + months
    y, m = d.year + m // 12, m % 12 + 1
    last = calendar.monthrange(y, m)[1]
    return date(y, m, min(d.day, last))

def add_month_overflow(d, months=1):
    m = d.month - 1 + months
    y, m = d.year + m // 12, m % 12 + 1
    last = calendar.monthrange(y, m)[1]
    if d.day <= last:
        return date(y, m, d.day)
    return date(y, m, last) + (date(d.year, d.month, d.day) - date(d.year, d.month, last))

start = date(2026, 1, 31)
print("start:            ", start)
print("clamp policy:     ", add_month_clamp(start))
print("overflow policy:  ", add_month_overflow(start))

import calendar
from datetime import date

def add_years(d, years, policy):
    y = d.year + years
    last = calendar.monthrange(y, d.month)[1]
    if d.day <= last:
        return date(y, d.month, d.day)
    return date(y, d.month, last) if policy == "clamp" else date(y, d.month + 1, 1)

