class WallClock:
    """Steps backwards by 60s mid-task, as an NTP step correction would."""
    def __init__(self):
        self.t = 1000.0
        self.calls = 0
    def now(self):
        self.calls += 1
        if self.calls == 2:
            self.t -= 60.0   # the step correction lands here
        return self.t
    def advance(self, s):
        self.t += s

class MonotonicClock:
    def __init__(self):
        self.t = 500.0
    def now(self):
        return self.t
    def advance(self, s):
        self.t += s

wall, mono = WallClock(), MonotonicClock()
w0, m0 = wall.now(), mono.now()
wall.advance(5); mono.advance(5)      # the task runs 5 seconds
w1, m1 = wall.now(), mono.now()
print("duration by wall clock:     ", w1 - w0, "seconds")
print("duration by monotonic clock:", m1 - m0, "seconds")

class FakeClock:
    def __init__(self, start=0.0):
        self.t = start
    def now(self):
        return self.t
    def advance(self, seconds):
        self.t += seconds

class TokenJar:
    TTL = 900
    def __init__(self, clock):
        self.clock = clock
        self.issued_at = None
    def issue(self):
        self.issued_at = self.clock.now()
    def valid(self):
        return self.clock.now() - self.issued_at < self.TTL

clock = FakeClock(start=10000.0)
jar = TokenJar(clock)
jar.issue()
for step in (899, 1, 1):
    clock.advance(step)
    print(f"at +{clock.now() - 10000.0:.0f}s -> valid? {jar.valid()}")

