def fetch_with_retry(attempt_fn, sleeper, max_attempts=4):
    delay = 1
    for attempt in range(1, max_attempts + 1):
        try:
            return attempt_fn()
        except ConnectionError:
            if attempt == max_attempts:
                raise
            sleeper(delay)
            delay *= 2

